def transforms(mask):
    mats=[]
    pts=list(mask)
    for refl in [False,True]:
      for k in range(4):
        q=[]
        for r,c in pts:
          if refl: c=-c
          for _ in range(k): r,c=c,-r
          q.append((r,c))
        minr=min(r for r,c in q); minc=min(c for r,c in q)
        q=frozenset((r-minr,c-minc) for r,c in q)
        if q not in mats:mats.append(q)
    return mats
